//! Raw oneVPL (Intel Video Processing Library) declarations, plus the three libva
//! entry points the Linux runtime needs.
//!
//! `vpl_api` is generated by bindgen from Intel's libvpl API headers (oneVPL API
//! 2.13, MIT licence: "Copyright Intel Corporation"). Its layout assertions are
//! compile-time, so a target whose ABI differs from the one the bindings were
//! generated on (Linux x86_64) fails to build instead of passing wrong structures
//! to the runtime. The headers pack every structure explicitly (`pack(4)` or
//! `pack(8)` on 64-bit targets, the same on Windows and Linux). Functions are not
//! generated: the dispatcher is opened at run time and the entry points below are
//! looked up by name.

#![allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    dead_code,
    missing_docs,
    unnecessary_transmutes,
    unused_imports,
    clippy::all,
    clippy::undocumented_unsafe_blocks
)]

#[rustfmt::skip]
pub(crate) mod vpl_api;

use core::ffi::{c_int, c_void};

pub(crate) use vpl_api::*;

/// `MFX_STRUCT_VERSION(1, 1)`, the version of `mfxVariant`.
pub(crate) const MFX_VARIANT_VERSION: u16 = (1 << 8) | 1;

/// Property name of the implementation-type filter, NUL-terminated.
pub(crate) const FILTER_IMPL: &[u8] = b"mfxImplDescription.Impl\0";

pub(crate) type MFXLoadFn = unsafe extern "C" fn() -> mfxLoader;
pub(crate) type MFXUnloadFn = unsafe extern "C" fn(mfxLoader);
pub(crate) type MFXCreateConfigFn = unsafe extern "C" fn(mfxLoader) -> mfxConfig;
pub(crate) type MFXSetConfigFilterPropertyFn =
    unsafe extern "C" fn(mfxConfig, *const mfxU8, mfxVariant) -> mfxStatus;
pub(crate) type MFXEnumImplementationsFn =
    unsafe extern "C" fn(mfxLoader, mfxU32, mfxImplCapsDeliveryFormat, *mut mfxHDL) -> mfxStatus;
pub(crate) type MFXDispReleaseImplDescriptionFn =
    unsafe extern "C" fn(mfxLoader, mfxHDL) -> mfxStatus;
pub(crate) type MFXCreateSessionFn =
    unsafe extern "C" fn(mfxLoader, mfxU32, *mut mfxSession) -> mfxStatus;
pub(crate) type MFXCloseFn = unsafe extern "C" fn(mfxSession) -> mfxStatus;
pub(crate) type MFXVideoCORE_SetHandleFn =
    unsafe extern "C" fn(mfxSession, mfxHandleType, mfxHDL) -> mfxStatus;
pub(crate) type MFXVideoCORE_SyncOperationFn =
    unsafe extern "C" fn(mfxSession, mfxSyncPoint, mfxU32) -> mfxStatus;
pub(crate) type MFXVideoENCODE_QueryFn =
    unsafe extern "C" fn(mfxSession, *mut mfxVideoParam, *mut mfxVideoParam) -> mfxStatus;
pub(crate) type MFXVideoENCODE_ParamFn =
    unsafe extern "C" fn(mfxSession, *mut mfxVideoParam) -> mfxStatus;
pub(crate) type MFXVideoENCODE_CloseFn = unsafe extern "C" fn(mfxSession) -> mfxStatus;
pub(crate) type MFXVideoENCODE_EncodeFrameAsyncFn = unsafe extern "C" fn(
    mfxSession,
    *mut mfxEncodeCtrl,
    *mut mfxFrameSurface1,
    *mut mfxBitstream,
    *mut mfxSyncPoint,
) -> mfxStatus;

/// The libva entry points used to give the Linux runtime a display.
pub(crate) mod va {
    use super::*;

    pub(crate) type VADisplay = *mut c_void;
    pub(crate) type VAStatus = c_int;
    pub(crate) const VA_STATUS_SUCCESS: VAStatus = 0;

    pub(crate) type GetDisplayDrmFn = unsafe extern "C" fn(c_int) -> VADisplay;
    pub(crate) type InitializeFn =
        unsafe extern "C" fn(VADisplay, *mut c_int, *mut c_int) -> VAStatus;
    pub(crate) type TerminateFn = unsafe extern "C" fn(VADisplay) -> VAStatus;
}
